    public void tryToSleep() {
        while (!isAsleep()) {
            countSomeSheep();
        }
    }

    private void countSomeSheep() {
        System.out.println("Tallying a lantern...");
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

