class DelegatingDeviceTracker {
    private final Map<String, String> positions = new HashMap<String, String>();

    public DelegatingDeviceTracker(Map<String, String> initial) {
        if (initial != null) {
            for (Map.Entry<String, String> entry : initial.entrySet()) {
                if (entry.getKey() != null && entry.getValue() != null) {
                    positions.put(entry.getKey(), entry.getValue());
                }
            }
        }
    }

    public synchronized String fetchPosition(String gadgetId) {
        if (gadgetId == null) {
            return null;
        }
        return positions.get(gadgetId);
    }

    public synchronized boolean updatePosition(String gadgetId, String position) {
        if (gadgetId == null || position == null || !positions.containsKey(gadgetId)) {
            return false;
        }
        positions.put(gadgetId, position);
        return true;
    }

    public synchronized Map<String, String> getAllPositionsLive() {
        return Collections.unmodifiableMap(new HashMap<String, String>(positions));
    }

    public synchronized Map<String, String> getAllPositionsStatic() {
        return Collections.unmodifiableMap(new HashMap<String, String>(positions));
    }
}

