import java.util.Map;

public class BetterAttributeStore {
    private final Map<String, String> attributes = new HashMap<String, String>();

    public synchronized void put(String key, String value) {
        attributes.put(key, value);
    }

    public boolean userLocationMatches(String name, String regexp) {
        String key = name + ".location";
        String location;
        synchronized (this) {
            location = attributes.get(key);
        }
        if (location == null) {
            return false;
        }
        return simpleMatches(regexp, location);
    }

    private static boolean simpleMatches(String regexp, String text) {
        if (regexp == null || text == null) {
            return false;
        }
        return matchHere(regexp, 0, text, 0);
    }

    private static boolean matchHere(String regexp, int ri, String text, int ti) {
        if (ri == regexp.length()) {
            return ti == text.length();
        }
        char rc = regexp.charAt(ri);
        if (ri + 1 < regexp.length() && regexp.charAt(ri + 1) == '*') {
            if (matchHere(regexp, ri + 2, text, ti)) {
                return true;
            }
            while (ti < text.length() && (rc == '.' || text.charAt(ti) == rc)) {
                ti++;
                if (matchHere(regexp, ri + 2, text, ti)) {
                    return true;
                }
            }
            return false;
        }
        if (ti < text.length() && (rc == '.' || rc == text.charAt(ti))) {
            return matchHere(regexp, ri + 1, text, ti + 1);
        }
        return false;
    }

    public static void main(String[] args) {
        final BetterAttributeStore store = new BetterAttributeStore();
        store.put("u1.location", "ny");
        final String name = "u1";
        Thread t1 = new Thread(() -> {
            try {
                System.out.println(store.userLocationMatches(name, "."));
            } catch (Throwable t) {
                System.out.println("t1 error: " + t);
            }
        });
        Thread t2 = new Thread(() -> {
            try {
                System.out.println(store.userLocationMatches(name, "n."));
            } catch (Throwable t) {
                System.out.println("t2 error: " + t);
            }
        });
        t1.start();
        t2.start();
        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

